// BAD: Improper use of Java API leading to vulnerabilities
// Example: Using ScriptEngine to eval untrusted input (Remote Code Execution) and unsafe SQL concatenation (SQL Injection)
import javax.script.ScriptEngineManager;
import javax.script.ScriptEngine;
import javax.script.ScriptException;
import javax.servlet.http.*;
import java.io.IOException;
import java.sql.*;

public class InsecureController extends HttpServlet {
    private Connection conn;

    @Override
    public void init() {
        try {
            // Assume a valid JDBC URL, user, pass
            conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "user", "pass");
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String expr = req.getParameter("calc"); // user-controlled input
        String username = req.getParameter("user"); // user-controlled input

        // vulnerable: Evaluates attacker-controlled input as code
        ScriptEngine engine = new ScriptEngineManager().getEngineByName("nashorn");
        try {
            Object result = engine.eval(expr); // RCE risk
            resp.getWriter().println("Calc result: " + result);
        } catch (ScriptException e) {
            resp.getWriter().println("Error: " + e.getMessage());
        }

        // vulnerable: SQL Injection via string concatenation
        String sql = "SELECT id, email FROM accounts WHERE username = '" + username + "'";
        try (Statement st = conn.createStatement();
             ResultSet rs = st.executeQuery(sql)) {
            while (rs.next()) {
                resp.getWriter().println("User ID: " + rs.getInt("id") + ", Email: " + rs.getString("email"));
            }
        } catch (SQLException e) {
            resp.getWriter().println("DB error: " + e.getMessage());
        }
    }
}

***
/**
 * GOOD: Safe alternatives to avoid vulnerable patterns
 * - Avoid dynamic code execution
 * - Use PreparedStatement for SQL queries
 * - Validate and constrain input
 */
import javax.servlet.http.*;
import java.io.IOException;
import java.sql.*;
import java.util.regex.Pattern;

public class SecureController extends HttpServlet {
    private Connection conn;

    // Strict allowlist for expressions: only digits and + - * / whitespace
    private static final Pattern SAFE_EXPR = Pattern.compile("^[0-9+\\-*/()\\s]{1,50}$");
    private static final Pattern SAFE_USERNAME = Pattern.compile("^[a-zA-Z0-9_]{3,32}$");

    @Override
    public void init() {
        try {
            conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "user", "pass");
            conn.setReadOnly(true); // extra defense for read-only endpoints
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    // Simple safe evaluator for arithmetic without using a script engine
    private int safeEvalSimple(String expr) throws IllegalArgumentException {
        if (expr == null || !SAFE_EXPR.matcher(expr).matches()) {
            throw new IllegalArgumentException("Invalid expression");
        }
        // Minimal parser example: rely on a vetted library in real apps (e.g., exp4j)
        // Here we only demonstrate avoiding ScriptEngine; production should use libraries.
        try {
            // Very basic approach using Java's built-in JavaScript is removed.
            // Replace with a simple stack-based evaluator or a library.
            // Placeholder: accept only integers, return parsed integer for demo.
            return Integer.parseInt(expr.trim());
        } catch (Exception e) {
            throw new IllegalArgumentException("Unsupported expression");
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String expr = req.getParameter("calc");
        String username = req.getParameter("user");

        // Avoid evaluating code; validate and process safely
        try {
            int result = safeEvalSimple(expr);
            resp.getWriter().println("Calc result: " + result);
        } catch (IllegalArgumentException ex) {
            resp.getWriter().println("Invalid input");
        }

        // Use parameterized queries to prevent SQL Injection
        if (username == null || !SAFE_USERNAME.matcher(username).matches()) {
            resp.getWriter().println("Invalid username");
            return;
        }

        String sql = "SELECT id, email FROM accounts WHERE username = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, username);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    resp.getWriter().println("User ID: " + rs.getInt("id") + ", Email: " + rs.getString("email"));
                }
            }
        } catch (SQLException e) {
            // Do not leak internal details
            resp.getWriter().println("Database error");
        }
    }
}

